def parts(g,corners,at):
    read=lambda key,kind='FLOAT':c._read(g,corners,key,at,kind)
    kind=read('st_pc_kind','INT');nose=g.math('COMPARE',kind,2.);bridge=g.math('COMPARE',kind,1.)
